"""Content CSVs = hand-written head + one GENERATED section per generator. Each generator rewrites only its section
(and, for gen_campaign.py, the head rows it is documented to adjust)."""
import csv
import io
import os

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
SRC = os.path.join(ROOT, 'Assets', '_Game', 'Content', 'Source')

MARKERS = {
    'gen_roster': '# ---- GENERATED by tools/content/gen_roster.py: edit roster_design.py and re-run ----',
    'gen_campaign': '# ---- GENERATED by tools/content/gen_campaign.py: edit campaign_design*.py and re-run ----',
}
ORDER = ['gen_roster', 'gen_campaign']


def read(name):
    """Returns (head text ending in a newline, {section: text})."""
    with open(os.path.join(SRC, name), newline='') as f:
        text = f.read()
    positions = sorted((text.find(m), k) for k, m in MARKERS.items() if m in text)
    cut = positions[0][0] if positions else len(text)
    head = text[:cut].rstrip('\n') + '\n'
    sections = {}
    for i, (pos, key) in enumerate(positions):
        end = positions[i + 1][0] if i + 1 < len(positions) else len(text)
        sections[key] = text[pos + len(MARKERS[key]):end].strip('\n')
    return head, sections


def rows(text):
    return [r for r in csv.reader(io.StringIO(text)) if r and not r[0].startswith('#')]


def to_text(rows_):
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator='\n')
    for r in rows_:
        w.writerow(r)
    return buf.getvalue().rstrip('\n')


def write(name, head, sections):
    out = head.rstrip('\n') + '\n'
    for key in ORDER:
        if sections.get(key):
            out += MARKERS[key] + '\n' + sections[key].rstrip('\n') + '\n'
    with open(os.path.join(SRC, name), 'w', newline='') as f:
        f.write(out)


def update(name, key, rows_):
    """Replaces one generator's section of a CSV, keeping the head and the other sections."""
    head, sections = read(name)
    sections[key] = to_text(rows_)
    write(name, head, sections)
